/** Submit a form once at a time and keep errors visible until the user resolves them. */
function useSubmit(done: () => void) {
  const [error, setError] = useState(''), [busy, setBusy] = useState(false);
  /** Run an explicit save, reporting both validation and network failures. */
  async function submit(run: () => Promise<unknown>) {
    if (busy) return;
    setError(''); setBusy(true);
    try { await run(); done(); }
    catch (e) { setError(e instanceof Error ? e.message : 'Save failed'); }
    finally { setBusy(false); }
  }
  return { error, busy, submit };
}

